// Manual maintainer build; never called by the QA runner. No downloads.
import { spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const args = process.argv.slice(2);
if (args.length !== 4 || args[0] !== "--sdk" || args[2] !== "--jdk") throw new Error("Usage: node build-helper.mjs --sdk <SDK> --jdk <JDK17>");
const sdk = fs.realpathSync(args[1]);
const jdk = fs.realpathSync(args[3]);
const source = path.join(here, "HierarchyDump.java");
const androidJar = path.join(sdk, "platforms/android-35/android.jar");
const work = fs.mkdtempSync(path.join(os.tmpdir(), "pi-ui-qa-helper-build-"));
function run(executable, argv) {
	const result = spawnSync(executable, argv, { cwd: work, env: { ...process.env, JAVA_HOME: jdk }, encoding: "utf8" });
	if (result.status !== 0) throw new Error(`${path.basename(executable)} failed: ${result.stderr}`);
}
function classes(dir) { return fs.readdirSync(dir, { withFileTypes: true }).flatMap((entry) => entry.isDirectory() ? classes(path.join(dir, entry.name)) : entry.name.endsWith(".class") ? [path.join(dir, entry.name)] : []); }
const sha = (bytes) => createHash("sha256").update(bytes).digest("hex");

// One stored ZIP entry with fixed timestamps: the bundle has no JAR metadata
// or build-directory paths. ART loads the D8 classes.dex directly from it.
function zipDex(dex) {
	const name = Buffer.from("classes.dex");
	let crc = 0xffffffff;
	for (const byte of dex) {
		crc ^= byte;
		for (let bit = 0; bit < 8; bit++) crc = crc >>> 1 ^ (crc & 1 ? 0xedb88320 : 0);
	}
	crc = (crc ^ 0xffffffff) >>> 0;
	const local = Buffer.alloc(30);
	local.writeUInt32LE(0x04034b50); local.writeUInt16LE(20, 4); local.writeUInt16LE(33, 12);
	local.writeUInt32LE(crc, 14); local.writeUInt32LE(dex.length, 18); local.writeUInt32LE(dex.length, 22); local.writeUInt16LE(name.length, 26);
	const central = Buffer.alloc(46);
	central.writeUInt32LE(0x02014b50); central.writeUInt16LE(20, 4); central.writeUInt16LE(20, 6); central.writeUInt16LE(33, 14);
	central.writeUInt32LE(crc, 16); central.writeUInt32LE(dex.length, 20); central.writeUInt32LE(dex.length, 24); central.writeUInt16LE(name.length, 28);
	const end = Buffer.alloc(22);
	end.writeUInt32LE(0x06054b50); end.writeUInt16LE(1, 8); end.writeUInt16LE(1, 10);
	end.writeUInt32LE(central.length + name.length, 12); end.writeUInt32LE(local.length + name.length + dex.length, 16);
	return Buffer.concat([local, name, dex, central, name, end]);
}
try {
	const output = path.join(work, "classes");
	const dex = path.join(work, "dex");
	fs.mkdirSync(output); fs.mkdirSync(dex);
	run(path.join(jdk, "bin/javac"), ["--release", "8", "-g:none", "-classpath", androidJar, "-d", output, source]);
	run(path.join(sdk, "build-tools/35.0.0/d8"), ["--release", "--min-api", "30", "--lib", androidJar, "--output", dex, ...classes(output).sort()]);
	const bytes = zipDex(fs.readFileSync(path.join(dex, "classes.dex")));
	if (bytes.length > 32 * 1024) throw new Error("helper exceeds 32KiB bundle limit");
	const bundle = `// GENERATED by helper/build-helper.mjs; Java17, build-tools35.0.0, API30 minimum.\nexport const HELPER_SHA256 = ${JSON.stringify(sha(bytes))};\nexport const HELPER_SOURCE_SHA256 = ${JSON.stringify(sha(fs.readFileSync(source)))};\nexport const HELPER_BASE64 = ${JSON.stringify(bytes.toString("base64"))};\n`;
	fs.writeFileSync(path.join(here, "../helper-bundle.mjs"), bundle);
	console.log(`Built trusted helper: ${bytes.length} bytes, SHA256 ${sha(bytes)}`);
} finally { fs.rmSync(work, { recursive: true, force: true }); }
